				Type:    "avatar",
				Name:    "Avatar",
				X:       41,
				Y:       41,
				Width:   200,
				Height:  200,
				Opacity: 1,
				URL:     nil,
				Radius:  levelingFloat(100),
				Fit:     levelingStr("cover"),
			},
			{
				ID:         "username",
				Type:       "text",
				Name:       "Usuario",
				X:          281,
				Y:          44,
				Width:      500,
