				Opacity:    1,
				Content:    levelingStr("{user}"),
				Color:      levelingStr("#ffffff"),
				FontSize:   levelingFloat(40),
				FontWeight: levelingInt(700),
				TextAlign:  levelingStr("left"),
			},
			{
				ID:         "level",
				Type:       "text",
