44	function accountCreatedAtMs(userId: string): number {
45		try {
46			return Number((BigInt(userId) >> 22n) + DISCORD_EPOCH_MS);
47		} catch {
48			return 0;
49		}
50	}
51	
52	/** Emoji custom de Discord: `<:nombre:id>` (estático) o `<a:nombre:id>` (animado). */
53	const CUSTOM_EMOJI_RE = /<a?:\w+:\d+>/g;
54	
55	/**
56	 * Segmentador de grafemas: agrupa una secuencia emoji completa (base + selector
57	 * de presentación + ZWJ + modificador de tono de piel + bandera + keycap) en UN
58	 * solo "carácter visual" — que es justo la unidad que hay que clasificar como
59	 * "emoji" o "no emoji". Trocear por code point suelto rompería, por ejemplo, una
60	 * bandera (dos code points) o una familia (varios emojis unidos por ZWJ).
61	 */
62	const graphemes = new Intl.Segmenter(undefined, { granularity: "grapheme" });
63	
64	/**
65	 * ¿Este grafema (ya segmentado) es un emoji unicode? `\p{Extended_Pictographic}`
66	 * cubre la inmensa mayoría (incluye el emoji base de las secuencias ZWJ/tono de
67	 * piel, ya fundidas en el mismo grafema por el segmentador de arriba). Aparte,
68	 * dos familias que esa propiedad NO cubre y sí son emoji real:
69	 *   - Banderas de país: dos "Regional Indicator" (🇪+🇸 → 🇪🇸), sin ningún code
70	 *     point pictográfico.
71	 *   - Keycaps: dígito/`#`/`*` + selector opcional + U+20E3 (1️⃣) — el carácter
72	 *     base tampoco es pictográfico (a propósito: si lo fuera, un "5" suelto ya
73	 *     contaría como emoji).
74	 * Deliberadamente NO se usa `\p{Emoji}` a secas: esa propiedad SÍ marca dígitos,
75	 * `#` y `*` (participan en keycaps), así que un mensaje "hay 5 sitios libres" se
76	 * leería como "solo emoji".
77	 */
78	function isEmojiGrapheme(cluster: string): boolean {
79		if (/\p{Extended_Pictographic}/u.test(cluster)) return true;
80		if (/^\p{Regional_Indicator}{2}$/u.test(cluster)) return true;
81		if (/^[0-9#*]\uFE0F?\u20E3$/u.test(cluster)) return true;
82		return false;
83	}
84	
85	/**
86	 * ¿El contenido (ya recortado, NO vacío) es solo emojis — unicode y/o custom? Quita
87	 * primero los custom (patrón propio, no son un grafema unicode) y trocea el resto
88	 * en grafemas: si TODOS son espacio o emoji, es "solo emoji". Vacío tras quitar los
89	 * custom (ej. `"<:ok:1><:ok:2>"`) cuenta como "solo emoji" trivialmente — no queda
90	 * ningún grafema que lo contradiga.
91	 */
92	function isEmojiOnlyContent(trimmedContent: string): boolean {
93		const withoutCustom = trimmedContent.replace(CUSTOM_EMOJI_RE, "");
94		for (const { segment } of graphemes.segment(withoutCustom)) {
95			if (/^\s+$/.test(segment)) continue;
96			if (!isEmojiGrapheme(segment)) return false;
97		}
98		return true;
99	}
100	
101	/** URL con o sin esquema (`https://…`, `www.…`). Heurística simple a propósito: para
102	 *  decidir "el mensaje es solo un enlace" no hace falta un validador RFC 3986. */
103	const URL_RE = /https?:\/\/\S+|www\.\S+/gi;
104	
105	/**
106	 * ¿Hay que descartar por "solo emoji o sticker" (`ignore_sticker_or_emoji_only`)?
107	 * Dos casos bajo el mismo interruptor:
108	 *   - Sin texto (tras recortar) pero CON sticker: el sticker ES el mensaje.
109	 *   - Con texto, pero ese texto es solo emoji (unicode y/o custom).
110	 * Sin texto y sin sticker (por ejemplo, solo un adjunto) NO cae aquí — eso lo cubre
111	 * `ignore_attachment_only`, un interruptor aparte.
112	 */
113	function isStickerOrEmojiOnly(trimmedContent: string, hasStickers: boolean): boolean {
114		if (trimmedContent.length === 0) return hasStickers;
115		return isEmojiOnlyContent(trimmedContent);
116	}
117	
118	/**
119	 * `true` = el miembro puede ganar XP con este evento (mensaje o tirada de voz).
120	 * Orden deliberado: primero el bypass (corta todo lo demás), luego las dos
121	 * antigüedades (aplican también en voz), y al final los cinco requisitos que
122	 * SOLO existen en texto (`ctx.message` ausente ⇒ ya se ha cumplido todo).
123	 */
124	export function meetsRequirements(reqs: DBLevelingRequirements, ctx: RequirementContext): boolean {
125		// Bypass total: un rol de bypass hace que el miembro cumpla SIEMPRE, sin
126		// evaluar nada más (ni siquiera la antigüedad). Staff, boosters, etc.
127		if (reqs.bypass_role_ids.some((id) => ctx.roleIds.includes(id))) return true;
128	
129		if (reqs.min_membership_seconds > 0 && ctx.joinedAt !== null) {
130			// Caché fría (`ctx.joinedAt === null`): esta rama ni se entra, así que el
131			// requisito NO se evalúa y el miembro se concede por defecto. Es la misma
132			// decisión que ya toma `resolveSessionCredit` en el ticker de voz cuando
133			// no puede leer el estado de voz de una sesión (se salta el paso sin
134			// penalizar): "no se pudo comprobar" no es lo mismo que "no cumple".
135			// Castigar por un fallo de infraestructura (una caché de miembros que
136			// aún no se ha poblado) sería peor que el abuso que este requisito busca
137			// cortar. Deliberado y no obvio — no "arreglar" a un `?? 0`.
138			const membershipSeconds = (Date.now() - ctx.joinedAt) / 1000;
139			if (membershipSeconds < reqs.min_membership_seconds) return false;
140		}
141	
142		if (reqs.min_account_age_seconds > 0) {
143			const accountAgeSeconds = (Date.now() - accountCreatedAtMs(ctx.userId)) / 1000;
144			if (accountAgeSeconds < reqs.min_account_age_seconds) return false;
145		}
146	
147		// Todo lo que sigue es SOLO TEXTO: en voz `ctx.message` es `undefined` y no
148		// hay nada más que comprobar.
149		if (!ctx.message) return true;
150	
151		const { content, hasAttachments, hasStickers, prefix } = ctx.message;
152		const trimmed = content.trim();
153	
154		if (reqs.min_message_length > 0 && trimmed.length < reqs.min_message_length) return false;
155		if (reqs.ignore_link_only && trimmed.length > 0 && trimmed.replace(URL_RE, "").trim().length === 0) return false;
156		if (reqs.ignore_attachment_only && hasAttachments && trimmed.length === 0) return false;
157		if (reqs.ignore_sticker_or_emoji_only && isStickerOrEmojiOnly(trimmed, hasStickers)) return false;
158		if (reqs.ignore_commands && prefix.length > 0 && trimmed.startsWith(prefix)) return false;
159	
160		return true;
161	}
