1	package validations
2	
3	import (
4		"strconv"
5	
6		"kena.bot/api-db-go/internal/domain/dbguild"
7		apierrors "kena.bot/api-db-go/internal/domain/errors"
8	)
9	
10	// UpdateModuleGreeterBody mirrors the Node `updateModuleGreeterSchema`
11	// (which is `greeterSchema.partial()`). All fields are pointers so the
12	// strict decoder can validate the shape (enums / nested structs) before
13	// the handler re-decodes the raw body as `map[string]any` and forwards
14	// it to the repository, which `mongo.MergeDeepJSON`-merges it into the
15	// existing subdoc by KEY PRESENCE (a key absent in the body is left
16	// alone; an explicit `false`/`0`/`""`/`null` is applied and overrides
17	// the stored value; nested objects recurse; slices replace wholesale;
18	// maps merge per-key).
19	//
20	// PER OLA-3 NOTE: this body is NOT strict. The handler binds with Fiber's
21	// default decoder (`c.Bind().Body`), which silently drops unknown keys —
22	// parity with Mongoose, same as logs/music. Only modmail/tempvoice/giveaway/
23	// moderation call `DisallowUnknownFields`; see the matching note in
24	// `module_tempvoice_validations.go`.
25	//
26	// Consequence to keep in mind: a client typo returns 200 as if it had been
27	// applied. It does not corrupt data — `MergeDeepJSON` drops any key that
28	// matches no json tag — and the server-owned fields (`schema_version`,
29	// `updated_at`, `enabled_since`) are re-stamped by the repository even if a
30	// client sends them, which is what keeps the write-once `enabled_since`
31	// invariant safe. See `module_greeter_repository.go`.
32	type UpdateModuleGreeterBody struct {
33		Enabled *bool                         `json:"enabled,omitempty"`
34		Welcome *dbguild.GreeterMessageConfig `json:"welcome,omitempty"`
35		Goodbye *dbguild.GreeterMessageConfig `json:"goodbye,omitempty"`
36		Boost   *dbguild.GreeterMessageConfig `json:"boost,omitempty"`
37		// Hermano de `boost` en la forma, pero depende de él en comportamiento:
38		// la reacción marca el mensaje que `boost` publica (ver
39		// `DBGreeterBoostReaction` en library-shared). Va fuera porque `boost`
40		// comparte forma con welcome/goodbye, donde no significaría nada.
41		BoostReaction *dbguild.GreeterBoostReaction `json:"boost_reaction,omitempty"`
42		JoinRoles     *dbguild.JoinRoles            `json:"join_roles,omitempty"`
43		Captcha       *dbguild.GreeterCaptcha       `json:"captcha,omitempty"`
44		Variables     *dbguild.GreeterVariables     `json:"variables,omitempty"`
45	}
46	
47	// Límites duros de la API de Discord. No son gusto nuestro: pasarse de aquí
48	// hace que Discord rechace el mensaje con 400 y la bienvenida NUNCA salga -en
49	// silencio, porque el error sólo aparece en los logs del bot-. Antes no había
50	// tope en ninguna capa: ni aquí, ni en el zod del dashboard. 32 KB de
51	// `message.content` se persistían tan contentos y el guild se quedaba sin
52	// bienvenidas para siempre.
53	const (
54		maxGreeterContent     = 2000
55		maxGreeterEmbedTitle  = 256
56		maxGreeterEmbedDesc   = 4096
57		maxGreeterEmbedFooter = 2048
58		maxGreeterURL         = 2048
59		maxGreeterButtonLabel = 80
60	
61		// Discord no deja más de 250 roles por servidor, así que una lista más
62		// larga sólo puede ser basura o un intento de ahogar al bot: asigna con un
63		// `for` secuencial y DOS llamadas a la API por rol.
64		maxJoinRoles = 250
65	
66		// Cada capa de tipo `image`/`avatar` es una descarga remota más, en serie,
67		// por cada miembro que entra.
68		maxCanvasElements = 100
69	
70		// 4096x4096 en RGBA son 64 MB de heap NATIVO, que `--max-old-space-size`
71		// no acota. Sin techo, `width: 50000` pedía ~10 GB y se llevaba por delante
72		// el proceso que sirve a TODOS los guilds.
73		maxCanvasSide = 4096
74	
75		// 14 días. Por encima de 2^31-1 milisegundos (~24,8 días) `setTimeout` de
76		// Node desborda, avisa con `TimeoutOverflowWarning` y coacciona el retardo
77		// a 1 ms: el mensaje que debía borrarse dentro de un mes se borraba al
78		// instante. Invertía la intención del usuario sin decir nada.
79		maxDelaySeconds = 14 * 24 * 60 * 60
80	)
81	
82	func maxLen(value *string, limit int, property string) *apierrors.CustomError {
83		if value == nil || len([]rune(*value)) <= limit {
84			return nil
85		}
86		return zodItemError(
87			"Too big: expected string to have <="+strconv.Itoa(limit)+" characters",
88			property,
89		)
90	}
91	
92	func inRange(value *int, limit int, property string) *apierrors.CustomError {
93		if value == nil {
94			return nil
95		}
96		if *value < 0 {
97			return zodItemError("Too small: expected number to be >=0", property)
98		}
99		if *value > limit {
100			return zodItemError(
101				"Too big: expected number to be <="+strconv.Itoa(limit),
102				property,
103			)
104		}
105		return nil
106	}
107	
108	func validateGreeterEmbed(e *dbguild.GreeterEmbed, prefix string) *apierrors.CustomError {
109		if e == nil {
110			return nil
111		}
112		for _, c := range []struct {
113			value    *string
114			limit    int
115			property string
116		}{
117			{e.Title, maxGreeterEmbedTitle, prefix + "title"},
118			{e.Description, maxGreeterEmbedDesc, prefix + "description"},
119			{e.Footer, maxGreeterEmbedFooter, prefix + "footer"},
120			{e.ImageURL, maxGreeterURL, prefix + "image_url"},
121			{e.ThumbnailURL, maxGreeterURL, prefix + "thumbnail_url"},
122		} {
123			if err := maxLen(c.value, c.limit, c.property); err != nil {
124				return err
125			}
126		}
127		return nil
128	}
129	
130	// validateGreeterImage aplica los topes del bloque `image` (tamaño de
131	// canvas, nº de elementos, longitud de URLs). Canal y privado comparten esta
132	// función -mismo tipo `dbguild.GreeterImage`, mismos límites- porque un
133	// canvas de privado puede llegar por PATCH directo igual que el de canal:
134	// nada en el transporte HTTP distingue a uno del otro, así que ambos
135	// necesitan el mismo candado. `prefix` ya incluye el segmento propio con el
136	// punto final (p.ej. "welcome.image." o "welcome.dm.image."), igual que hace
137	// validateGreeterEmbed con el suyo.
138	func validateGreeterImage(img *dbguild.GreeterImage, prefix string) *apierrors.CustomError {
139		if err := maxLen(img.BackgroundURL, maxGreeterURL, prefix+"background_url"); err != nil {
140			return err
141		}
142	
143		canvas := &img.Canvas
144		if canvas.Width > maxCanvasSide || canvas.Height > maxCanvasSide {
145			return zodItemError(
146				"Too big: expected number to be <="+strconv.Itoa(maxCanvasSide),
147				prefix+"canvas",
148			)
149		}
150		if canvas.Width < 0 || canvas.Height < 0 {
151			return zodItemError("Too small: expected number to be >=0", prefix+"canvas")
152		}
153		if len(canvas.Elements) > maxCanvasElements {
154			return zodItemError(
155				"Too big: expected array to have <="+strconv.Itoa(maxCanvasElements)+" items",
156				prefix+"canvas.elements",
157			)
158		}
159		if err := maxLen(
160			canvas.BackgroundURL,
161			maxGreeterURL,
162			prefix+"canvas.background_url",
163		); err != nil {
164			return err
165		}
166		for i := range canvas.Elements {
167			if err := maxLen(
168				canvas.Elements[i].URL,
169				maxGreeterURL,
170				prefix+"canvas.elements."+strconv.Itoa(i)+".url",
171			); err != nil {
172				return err
173			}
174		}
175		return nil
176	}
177	
