// BotWelcomeMessageBody is one welcome flow on the wire.
type BotWelcomeMessageBody struct {
	Enabled  *bool   `json:"enabled"`
	Template *string `json:"template"`
}

// Discord snowflake, mirroring `snowflakeSchema` in api-gateway's
// bot-validations. Enforced here too because api-db is also reachable
// directly (core boot, scripts) — the gateway is not the only writer.
var snowflakeRe = regexp.MustCompile(`^\d{17,20}$`)

// validateWhitelistGuilds mirrors `z.array(snowflakeSchema).max(1000)`.
func validateWhitelistGuilds(guilds []string) *apierrors.CustomError {
	if len(guilds) > 1000 {
		return zodItemError("Too big: expected array to have <=1000 items", "whitelist_guilds")
	}
	for _, g := range guilds {
		if !snowflakeRe.MatchString(g) {
			return zodItemError("Must be a Discord snowflake (17–20 digits)", "whitelist_guilds")
		}
	}
	return nil
}

// validateHiddenModuleTesters valida hidden_module_testers: cada clave debe
// ser un módulo válido (dbbot.IsValidModuleKey) y cada valor un snowflake de
// Discord, con un máximo de 100 ids por módulo — de sobra para una tanda de
// testers en pruebas sin convertir el campo en una lista de difusión sin
// límite. Reutiliza snowflakeRe (ver validateWhitelistGuilds): es la misma
// forma de id.
func validateHiddenModuleTesters(testers map[string][]string) *apierrors.CustomError {
	for key, ids := range testers {
		if !dbbot.IsValidModuleKey(key) {
			return zodItemError(`Invalid option: expected a valid module key`, "hidden_module_testers")
		}
		if len(ids) > 100 {
			return zodItemError("Too big: expected array to have <=100 items", "hidden_module_testers")
		}
		for _, id := range ids {
			if !snowflakeRe.MatchString(id) {
				return zodItemError("Must be a Discord snowflake (17–20 digits)", "hidden_module_testers")
			}
		}
	}
	return nil
}

