/**
 * Requisitos que un miembro debe cumplir para ganar XP de UNA fuente (texto
 * o voz — cada una lleva su PROPIA copia dentro de `DBLevelingSource` desde
 * v3, no es un único bloque compartido). Todos con "0 / false / lista vacía
 * = sin requisito", así que un guild que no los toque no nota absolutamente
 * nada: el bloque entero es opt-in.
 */
export interface DBLevelingRequirements {
	/**
	 * Segundos que el miembro debe llevar EN EL SERVIDOR antes de ganar XP.
	 * Sale de `joined_at` del miembro, que ya está en la caché de miembros:
	 * ninguna petición extra a Discord. 0 = sin requisito.
	 */
	min_membership_seconds: number;
	/**
	 * Antigüedad mínima de la CUENTA de Discord, en segundos. Se deduce del
	 * snowflake del propio id de usuario (los 42 bits altos son el timestamp),
	 * así que tampoco cuesta ninguna petición. 0 = sin requisito.
	 */
	min_account_age_seconds: number;
	/** SOLO TEXTO. Caracteres mínimos del mensaje, ya recortado. 0 = cualquiera. */
	min_message_length: number;
	/** SOLO TEXTO. Descarta el mensaje cuyo contenido, quitado el enlace, queda vacío. */
	ignore_link_only: boolean;
	/** SOLO TEXTO. Descarta el mensaje sin texto que solo trae adjuntos. */
	ignore_attachment_only: boolean;
	/** SOLO TEXTO. Descarta el mensaje que solo son emojis (unicode o custom) o un sticker. */
	ignore_sticker_or_emoji_only: boolean;
	/** SOLO TEXTO. Descarta el mensaje que empieza por el prefijo del servidor. */
	ignore_commands: boolean;
	/** Roles que se saltan TODOS los requisitos anteriores (staff, boosters…). */
	bypass_role_ids: string[];
}

/** Requisitos por defecto: todo a 0 / false / lista vacía — el bloque entero
 *  nace opt-in, así que activar el módulo no le cambia nada a un guild que
 *  no lo toque. Mismo objeto compartido entre `DEFAULT_LEVELING_SOURCE_TEXT`
 *  y `DEFAULT_LEVELING_SOURCE_VOICE` (fiel a `DBGuildSchemas.ts`): es
 *  seguro — el form nunca muta en sitio, siempre reemplaza por un objeto
 *  nuevo en el campo que se edita. */
