// LevelingRequirements mirrors `DBLevelingRequirements` — requisitos que un
// miembro debe cumplir para ganar XP de ESTA fuente (texto o voz; cada una
// lleva su PROPIA copia dentro de `LevelingXpSource`, no es un único bloque
// compartido). Todos con "0 / false / lista vacía = sin requisito", así que
// el bloque entero es opt-in: un guild que no lo toque no nota nada.
// Existen para el abuso — la cuenta recién creada que entra, farmea nivel a
// mensajes de una letra y se va —, no para la burocracia.
//
// Los cinco campos desde `MinMessageLength` son SOLO TEXTO: se persisten
// igual en `Voice` por simetría de forma con `Text` (mismo tratamiento que
// `LevelingVoiceRules` en el bloque de texto), pero ahí se ignoran.
type LevelingRequirements struct {
	// MinMembershipSeconds: segundos que el miembro debe llevar EN EL
	// SERVIDOR antes de ganar XP. 0 = sin requisito.
	MinMembershipSeconds int `bson:"min_membership_seconds" json:"min_membership_seconds"`
