// NewModuleLeveling son los DEFAULTS de fábrica del módulo de niveles —
// espejo campo a campo de `DEFAULT_LEVELING_*` en DBGuildSchemas.ts (§5 de
// la spec del lote). Un default que falte aquí es deriva silenciosa de datos
// en la primera escritura, así que este fichero tiene que ir en paralelo con
// el TS: si tocas uno, toca el otro.
//
// `announce.content` es el CENTINELA — mientras el guild lo conserve BYTE A
// BYTE igual a este literal, bot y dashboard lo traducen con la clave i18n
// `announceDefault` en vez de mostrarlo tal cual (mismo contrato que
// `DEFAULT_TEMPVOICE_PANEL`). Si cambias este string, coordínalo con el TS o
// el centinela deja de reconocerse en los guilds ya creados.
//
// `commands_global` no aparece explícito en el bloque de defaults de la spec
// (§5): se mirror-ea el criterio de `TTSCommandAccessDefault` — sin
// restricción en los tres ejes, que es lo único consistente con
// `commands.rank.use_global` naciendo en `true` en los tres.
//
// `updated_at` es el epoch (`new Date(0)` en TS), como en el resto de
// módulos con `updated_at` propio (greeter, tempvoice, tts).
func NewModuleLeveling() dbguild.ModuleLeveling {
	return dbguild.ModuleLeveling{
		SchemaVersion: dbguild.SchemaVersionLeveling,
		Enabled:       false,
		EnabledSince:  nil,
		XPMode:        dbguild.LevelingXPModeUnified,
		Text: dbguild.LevelingXpSource{
			Enabled:         true,
			Min:             15,
			Max:             25,
			IntervalSeconds: 60,
		},
		Voice: dbguild.LevelingXpSource{
			Enabled:         true,
			Min:             5,
			Max:             10,
			IntervalSeconds: 60,
		},
		CurveMultiplier: 1,
		VoiceRules: dbguild.LevelingVoiceRules{
			IgnoreAlone:    true,
			IgnoreMuted:    true,
			IgnoreDeafened: true,
		},
		ExcludedChannelIDs: []string{},
		ExcludedRoleIDs:    []string{},
		RoleMultipliers:    []dbguild.LevelingMultiplier{},
		ChannelMultipliers: []dbguild.LevelingMultiplier{},
		Announce: dbguild.LevelingAnnounce{
			Enabled:            true,
			Target:             dbguild.LevelingAnnounceTargetCurrent,
			ChannelID:          nil,
			Content:            "¡{mention} ha subido al nivel **{level}**!",
			DeleteAfterSeconds: nil,
		},
		Rewards: dbguild.LevelingRewards{
			Enabled:  false,
			Stacking: dbguild.LevelingRewardStackingStack,
			Levels:   []dbguild.LevelingReward{},
		},
		RankCard: dbguild.LevelingRankCard{
			Mode:          dbguild.LevelingCardBasic,
			BackgroundURL: nil,
			AccentColor:   "#5865F2",
			Canvas:        defaultLevelingCardCanvas(),
		},
		CommandsGlobal: levelingCommandAccessDefault(),
		Commands: map[string]dbguild.LevelingCommand{
			"rank": levelingConfigurableCommandDefault(),
		},
		CommandMode: dbguild.LevelingCommandModeBoth,
		UpdatedAt:   dbguild.NewDate(time.Unix(0, 0).UTC()),
	}
}

