// `voice.requirements`, `dbguild.LevelingRequirements`): mismos topes que el
// zod del dashboard (`leveling-schema.ts`, `MIN/MAX_REQUIREMENT_*`),
// reaplicados aquí porque este endpoint también acepta un PATCH directo con
// la credencial de api-db.
const (
	// Antigüedad exigible (tiempo en el servidor o edad de cuenta): comparten
	// rango porque comparten motivo. Techo de cordura de 10 años.
	maxLevelingRequirementAgeSeconds = 315_360_000
	// Coincide con el límite real de un mensaje de Discord: pedir más sería
	// un requisito que NINGÚN mensaje podría cumplir jamás.
	maxLevelingRequirementMessageLength = 2000
)

// validateLevelingRequirements aplica los topes del bloque de requisitos de
// UNA fuente (texto o voz). `prefix` ya incluye el segmento propio con el
// punto final (p.ej. "text.requirements." / "voice.requirements."), igual
// que el resto de validadores anidados del paquete.
func validateLevelingRequirements(r *dbguild.LevelingRequirements, prefix string) *apierrors.CustomError {
	if r == nil {
		return nil
	}
	if err := inRange(&r.MinMembershipSeconds, maxLevelingRequirementAgeSeconds, prefix+"min_membership_seconds"); err != nil {
		return err
	}
	if err := inRange(&r.MinAccountAgeSeconds, maxLevelingRequirementAgeSeconds, prefix+"min_account_age_seconds"); err != nil {
		return err
	}
	if err := inRange(&r.MinMessageLength, maxLevelingRequirementMessageLength, prefix+"min_message_length"); err != nil {
		return err
	}
	for _, id := range r.BypassRoleIDs {
		if !snowflakeRe.MatchString(id) {
			return zodItemError("Must be a Discord snowflake (17–20 digits)", prefix+"bypass_role_ids")
		}
	}
	return nil
}

