// el repositorio escribe lo que le llega, así que un `min_message_length:
// 99999` se guardaría tal cual y ningún mensaje lo cumpliría jamás. Un
// puntero `Text`/`Voice` nil es «no tocar ese bloque» y no se valida.
func ValidateUpdateModuleLeveling(body *UpdateModuleLevelingBody) *apierrors.CustomError {
	if body == nil {
		return nil
	}
	if body.Text != nil {
		if err := validateLevelingRequirements(&body.Text.Requirements, "text.requirements."); err != nil {
			return err
		}
	}
	if body.Voice != nil {
		if err := validateLevelingRequirements(&body.Voice.Requirements, "voice.requirements."); err != nil {
			return err
		}
	}
	return nil
}

