package redis

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/redis/rueidis"

	"kena.bot/api-db-go/internal/domain/dbguild"
)

// ModuleCache mirrors `DBModuleCache` in TS. Each module lives in its
// own Redis hash keyed by `bots:{botId}:guilds:{guildId}:modules:{moduleKey}`,
// matching the Node layout so external readers (other controllers, the
// music-module guild-picker) see the same shape.
//
// TTL: every SetModule call applies `ModuleTTLSeconds` when ttlSeconds is
// zero/unset. The TTL is a BACKSTOP, not the invalidation mechanism: every
// `Update` on a module repo is write-through and every delete invalidates
// explicitly, so a correct system never needs the timer. It exists only to
// bound the damage of a *missed* invalidation (a Redis blip that swallowed a
// DEL, a schema bump that left an unreadable hash) — the same reasoning as
// the `botsListTTLSeconds` backstop in bot_cache.go.
//
// It used to be 1 hour, which made the backstop the dominant cost of the
// whole service: every guild with any activity re-read its modules from
// Mongo once an hour whether or not anything had changed. See
// ANALISIS-CACHE.md — that single constant accounted for most of the
// ~30M monthly DB ops.
//
// The cache only stores the module subdoc (the `module_music` block of
// the guild doc), not the entire guild. This means module PATCHes do
// not invalidate the wider guild cache, but reading requires either a
// cache hit here or a fresh Mongo projection — which `ModuleRepository`
// handles.
type ModuleCache struct {
	client *Client
}

// ModuleTTLSeconds is the backstop TTL applied to module cache writes and to
// the `enabled_modules` snapshot. 24h, not 1h: at 1h the timer was firing
// ~24x more often than any real invalidation needed it to, and each firing
// cost a Mongo read per active guild.
//
// Not TTL-less (unlike the guild hash in guild_cache.go) on purpose: a missed
// invalidation on a module would leave a guild's module config wrong until
// something wrote to it again, which for a rarely-edited module means
// "forever". 24h bounds that at one day while removing 96% of the refreshes.
const ModuleTTLSeconds = 86400

// moduleKey is the canonical cache key for a single module subdoc.
// Mirrors `moduleKey()` in `libraries/library-shared/src/redis/cache/db-api/module-cache.ts`.
func (m *ModuleCache) moduleKey(botID, guildID, moduleKey string) string {
	return fmt.Sprintf("bots:%s:guilds:%s:modules:%s", botID, guildID, moduleKey)
}

// enabledModulesKey holds the SET of enabled module keys for a guild.
// Used by external consumers (dashboards, the music picker) to skip the
// HTTP round-trip on /modules/enabled, and by `listEnabled` itself as its
// cache fast-path.
func (m *ModuleCache) enabledModulesKey(botID, guildID string) string {
	return fmt.Sprintf("bots:%s:guilds:%s:enabled_modules", botID, guildID)
}

// enabledModulesSnapshotKey holds the cached answer to "which modules does this
// guild have enabled" as a JSON array — including the empty array.
//
// It exists because a Redis SET cannot be empty: SADD-ing zero members leaves
// no key, so in the SET alone "this guild has 0 enabled modules" and "we have
// never computed this guild's modules" are the same observable state. That
// ambiguity was not a corner case — a guild that added the bot and never ran
// `/config` is the most common guild there is, so the ambiguous branch was the
// hot branch, and every one of those guilds re-derived its empty module list
// from Mongo on a timer, forever.
//
// The answer lives in this ONE key rather than in a boolean marker beside the
// SET on purpose. Two keys with independent expiry can be observed
// half-expired: if the SET went first, a surviving marker would assert "no
// modules enabled" for a guild that has some. Reading a single key cannot
// produce that. The SET is still written for external consumers (dashboards,
// the music picker) that read `enabled_modules` directly, but it is no longer
// what `GetEnabledModules` trusts.
func (m *ModuleCache) enabledModulesSnapshotKey(botID, guildID string) string {
	return fmt.Sprintf("bots:%s:guilds:%s:enabled_modules_cached", botID, guildID)
}

// NewModuleCache builds a module cache on top of the shared Redis client.
func NewModuleCache(client *Client) *ModuleCache {
	return &ModuleCache{client: client}
}

// GetModule returns the deserialized module subdoc, or nil when missing.
// The returned map is the raw hash with each value deserialized via
// `DeserializeValue` (booleans, numbers, dates, JSON objects). The caller
// is responsible for unmarshalling into the typed `dbguild.ModuleMusic`
// (or greeter/logs) shape.
func (m *ModuleCache) GetModule(ctx context.Context, botID, guildID, moduleKey string) (map[string]any, error) {
	raw, err := m.client.HGetAll(ctx, m.moduleKey(botID, guildID, moduleKey))
	if err != nil || raw == nil {
		return nil, err
	}
	out := make(map[string]any, len(raw))
	for k, v := range raw {
		out[k] = DeserializeValue(v)
	}
	return out, nil
}

// SetModule writes the module subdoc with TTL=ModuleTTLSeconds by default
// (override via `ttlSeconds > 0`). The write is best-effort: a Redis
// failure is logged and swallowed so the caller can still return a
// successful response (the Mongo write already succeeded).
//
// The three Redis commands (DEL + HSET + EXPIRE) are pipelined in a
// single round-trip so the cache key never lands in an intermediate
// "fields from the previous schema_version, no TTL" state that a racing
// reader could observe. The DEL is the important part: without it the
// hash could carry stale fields from a prior schema bump indefinitely.
// The pipelined EXPIRE is the second important part: HSET on an existing
// key with no TTL is a no-op for the timer, so we have to (re-)arm the
// TTL atomically with the HSET — sequential HSET-then-EXPIRE would
// leave the key TTL-less if the second call failed.
//
// Side effects on the enabled SET are intentionally NOT performed here —
// the Node `setModule` clears the `enabled_modules_checked` tombstone but
// only the Node setModule variant (called from internal repo paths) does
// the SADD/SREM gymnastics. The Go port mirrors the simpler behaviour:
// just the module hash + TTL. The `enabled_modules` SET itself is
// maintained by `EnabledHandler.listEnabled` (see `SetEnabledModules`).
func (m *ModuleCache) SetModule(ctx context.Context, botID, guildID, moduleKey string, fields map[string]string, ttlSeconds int) error {
	if ttlSeconds <= 0 {
		ttlSeconds = ModuleTTLSeconds
	}
	if len(fields) == 0 {
		return nil
	}
	key := m.moduleKey(botID, guildID, moduleKey)
	resps := m.client.DoMulti(ctx,
		m.client.DelPipeline(key),
		m.client.HSetPipeline(key, fields),
		m.client.ExpirePipeline(key, ttlSeconds),
	)
	// All three commands must succeed for the write to be considered
	// committed. DEL is idempotent (returns 0 on missing key) so a non-
	// nil error there is a real network failure.
	for i, r := range resps {
		if err := r.Error(); err != nil {
			return fmt.Errorf("module cache pipeline step %d: %w", i, err)
		}
	}
	return nil
}

// DeleteModule removes the module subdoc. Used for cache invalidation
// before re-reading from Mongo (the `force` flag in the Node service
// also calls DEL+SET in this order).
func (m *ModuleCache) DeleteModule(ctx context.Context, botID, guildID, moduleKey string) error {
	return m.client.Del(ctx, m.moduleKey(botID, guildID, moduleKey))
}

// GetEnabledModules reads the cached snapshot of enabled module keys.
//
// The second return value is what makes this usable as a cache: it reports
// whether a snapshot EXISTS, independently of whether it is empty. `([], true,
// nil)` means "we computed this guild and it has no modules enabled" — a hit,
// answerable without Mongo. `(nil, false, nil)` means "never computed" and is
// the only case the caller must resolve against the database.
//
// A snapshot that fails to decode is reported as a miss rather than an error:
// the only cost is one resolve, which then overwrites the bad value. Same
// posture as the module hashes, which fall through to Mongo when their fields
// cannot be parsed.
func (m *ModuleCache) GetEnabledModules(ctx context.Context, botID, guildID string) ([]string, bool, error) {
	raw, found, err := m.client.Get(ctx, m.enabledModulesSnapshotKey(botID, guildID))
	if err != nil {
		return nil, false, err
	}
	if !found {
		return nil, false, nil
	}
	var keys []string
	if err := json.Unmarshal([]byte(raw), &keys); err != nil {
		return nil, false, nil
	}
	if keys == nil {
		keys = []string{}
	}
	return keys, true, nil
}

// SetEnabledModules writes both representations of the enabled-module snapshot:
// the JSON key `GetEnabledModules` reads, and the `enabled_modules` SET that
// external consumers (dashboards, the music picker) read directly.
//
// SET members are flat strings (`music`, `greeter`, `logs`) and both keys carry
// `ModuleTTLSeconds`, matching the per-module HASHes.
//
// An empty `keys` slice is NOT a no-op any more: it DELs the SET and writes an
// empty JSON array, which is how "this guild has no modules enabled" gets
// cached. That used to be skipped entirely, leaving the most common guild shape
// permanently uncacheable (see `enabledModulesSnapshotKey`).
//
// Single pipeline so the two representations cannot disagree for longer than a
// round-trip, and DEL-before-SADD so a shrinking module list drops members
// instead of accumulating them.
//
// Called from `EnabledHandler.listEnabled` once it has resolved the enabled
// keys. Best-effort: a Redis failure is returned to the caller, which logs it
// and still answers the request (the data in the response is already correct).
func (m *ModuleCache) SetEnabledModules(ctx context.Context, botID, guildID string, keys []string) error {
	setKey := m.enabledModulesKey(botID, guildID)
	snapshotKey := m.enabledModulesSnapshotKey(botID, guildID)

	if keys == nil {
		keys = []string{}
	}
	encoded, err := json.Marshal(keys)
	if err != nil {
		return fmt.Errorf("marshal enabled_modules snapshot: %w", err)
	}

	cmds := []rueidis.Completed{m.client.DelPipeline(setKey)}
	if len(keys) > 0 {
		cmds = append(cmds,
			m.client.SAddPipeline(setKey, keys...),
			m.client.ExpirePipeline(setKey, ModuleTTLSeconds),
		)
	}
	cmds = append(cmds, m.client.SetExPipeline(snapshotKey, string(encoded), ModuleTTLSeconds))

	for i, r := range m.client.DoMulti(ctx, cmds...) {
		if err := r.Error(); err != nil {
			return fmt.Errorf("enabled_modules pipeline step %d: %w", i, err)
		}
	}
	return nil
}

// DeleteEnabledSet removes both the enabled_modules SET and the JSON snapshot.
// Used when a guild is deleted (`bots_guilds_handler.Delete`), and by every
// module write via `invalidateEnabledSnapshot`.
//
// Both keys must go: leaving the snapshot behind would keep serving a stale
// answer — which, right after a module was enabled or disabled, is exactly the
// answer the caller must not get.
func (m *ModuleCache) DeleteEnabledSet(ctx context.Context, botID, guildID string) error {
	return m.client.DelMany(ctx, m.enabledModulesKey(botID, guildID), m.enabledModulesSnapshotKey(botID, guildID))
}

func mustJSON(v any) string {
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprintf("__MARSHAL_ERR__:%v", err)
	}
	return string(b)
}

// MarshalModuleMusic serializes a typed `dbguild.ModuleMusic` subdoc
// into the field-value pairs the HSET expects. Mirrors the
// `marshalGuildToHash` approach used by the guild cache but scoped to
// just the music fields. Exported for use by `ModuleMusicRepository`.
//
// The output is a flat string map; nested objects (`dj`, `radio_mode`,
// `text_channels`, `voice_channels`, the v5 `commands_global` object and
// `commands` map, array fields) are JSON-encoded once so the wire format is
// interchangeable with the Node `redisAdapter.cache.db.module.setModule`
// (whose `serializeValue` JSON.stringifies objects/maps field-for-field).
func MarshalModuleMusic(m dbguild.ModuleMusic) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	out["enabled"] = SerializeValue(m.Enabled)
	out["enabled_since"] = nullableDateField(m.EnabledSince)
	out["max_song_duration"] = SerializeValue(m.MaxSongDuration)
	out["loop"] = string(m.Loop)
	out["volume"] = SerializeValue(m.Volume)
	out["radio_mode"] = mustJSON(m.RadioMode)
	out["message_retention"] = SerializeValue(m.MessageRetention)
	out["pinned_now_playing"] = SerializeValue(m.PinnedNowPlaying)
	out["voice_status_enabled"] = SerializeValue(m.VoiceStatusEnabled)
	out["enhanced_search"] = SerializeValue(m.EnhancedSearch)
	out["auto_delete_commands"] = mustJSON(m.AutoDeleteCommands)
	out["audio_quality"] = string(m.AudioQuality)
	out["commands_global"] = mustJSON(m.CommandsGlobal)
	out["commands"] = mustJSON(m.Commands)
	out["text_channels"] = mustJSON(m.TextChannels)
	out["voice_channels"] = mustJSON(m.VoiceChannels)
	out["dj"] = mustJSON(m.DJ)
	out["recommended_artists"] = mustJSON(m.RecommendedArtists)
	return out, nil
}

// MarshalModuleGreeter serializes a typed `dbguild.ModuleGreeter` subdoc.
// Mirrors MarshalModuleMusic but for the greeter block.
//
// Nested objects (`welcome`, `goodbye`, `captcha`, `join_roles`,
// `variables`) are JSON-encoded; the `updated_at` date uses the
// `__DATE__:` prefix so the round-trip is lossless.
//
// The captcha block is optional — encoded as JSON-null when nil so the
// cache stays byte-compatible with the Node service which always emits
// the captcha subdoc (or absent in older migrations).
func MarshalModuleGreeter(m dbguild.ModuleGreeter) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	out["enabled"] = SerializeValue(m.Enabled)
	// `enabled_since` nullable: `__DATE__:<ISO>` cuando hay fecha, cadena
	// vacía cuando no — DeserializeValue("") devuelve nil, que decodifica
	// al puntero nil del struct (misma convención que nullableStringField).
	if m.EnabledSince != nil {
		out["enabled_since"] = dateField(m.EnabledSince.Time)
	} else {
		out["enabled_since"] = ""
	}
	putJSONInline(out, "welcome", m.Welcome)
	putJSONInline(out, "goodbye", m.Goodbye)
	putJSONInline(out, "boost", m.Boost)
	// ⚠️ Esta función es una lista de campos A MANO: lo que no se escriba aquí
	// NO se cachea, y como la caché se reescribe en cada PATCH y se sirve
	// mientras `schema_version` cuadre, el campo olvidado vuelve a su valor
	// cero en la siguiente lectura — se guarda en Mongo y "no se guarda" para
	// el usuario. Le pasó a `boost_reaction` recién nacido en v15. Si añades
	// un campo a `ModuleGreeter`, añádelo también aquí.
	putJSONInline(out, "boost_reaction", m.BoostReaction)
	putJSONInline(out, "join_roles", m.JoinRoles)
	// Captcha nullable: misma convención que `enabled_since` — cadena vacía
	// cuando no hay bloque. NO vale escribir la cadena "null": ni el
	// DeserializeValue de Go ni el de Node (RedisCacheClient.deserializeValue)
	// tienen un caso para ella, así que ambos la devolverían como el *string*
	// "null" y el bson.Unmarshal de mapToModuleGreeter abortaría entero con
	// "cannot decode string into a dbguild.GreeterCaptcha". FindModule
	// reaccionaría borrando la caché y releyendo Mongo, que reescribiría el
	// mismo valor: cache-miss permanente para ese guild.
	if m.Captcha != nil {
		putJSONInline(out, "captcha", *m.Captcha)
	} else {
		out["captcha"] = ""
	}
	putJSONInline(out, "variables", m.Variables)
	out["updated_at"] = dateField(m.UpdatedAt.Time)
	return out, nil
}

// putJSONInline is a marshaller-local variant of the package-private
// `putJSON` (defined in guild_cache.go). The greeter marshaller uses
// the inline form because the greeter marshaller signature returns
// `(map[string]string, error)` for consistency with the music
// marshaller, while the guild marshaller returns the same. To avoid
// breaking the existing `putJSON` contract (which propagates errors),
// the greeter path uses a fire-and-forget variant that writes a
// `__MARSHAL_ERR__:...` sentinel on failure. The next cache read will
// see the malformed field and fall back to Mongo, which is the same
// behavior the music marshaller follows.
func putJSONInline(out map[string]string, key string, v any) {
	b, err := json.Marshal(v)
	if err != nil {
		out[key] = fmt.Sprintf("__MARSHAL_ERR__:%v", err)
		return
	}
	out[key] = string(b)
}

// dateField encodes a `time.Time` as `__DATE__:<ISO>` — same form the
// generic `SerializeValue` uses but exposed here so the greeter
// marshaller doesn't have to import dbguild's JSONDate just to call it.
func dateField(t time.Time) string {
	return "__DATE__:" + t.UTC().Format("2006-01-02T15:04:05.000Z")
}

// MarshalModuleLogs serializes a typed `dbguild.ModuleLogs` subdoc.
// Logs are the simplest of the three modules: a single Ignore list
// (3 string arrays) plus an Events map (5 nullable channel ids).
// Everything serializes to a flat string per the Redis cache
// convention.
func MarshalModuleLogs(m dbguild.ModuleLogs) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	out["enabled"] = SerializeValue(m.Enabled)
	out["enabled_since"] = nullableDateField(m.EnabledSince)
	putJSONInline(out, "ignore", m.Ignore)
	putJSONInline(out, "events", m.Events)
	return out, nil
}

// MarshalModuleModmail serializes a typed `dbguild.ModuleModmail` subdoc.
// Mirrors the greeter/logs marshallers but for the (larger) modmail block.
//
// Scalars (schema_version, enabled, guild_id, log_auto_publish,
// special_types_in_main, ticket_type_emojis, anonymous_icon) go through SerializeValue; every
// nested object / array / map goes through putJSONInline (JSON). The four top-level nullable strings
// (log_channel_id, main_guild_id, contact_category_id,
// contact_channel_name_template) use `nullableStringField` so the wire value is
// "" for null — matching the Node `serializeValue(null) === ""` convention, so
// the cache hash stays interchangeable with the Node writer.
func MarshalModuleModmail(m dbguild.ModuleModmail) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	// `rev` tiene que sobrevivir al viaje por la caché: el `ETag` del GET se
	// construye con él, y una lectura caliente que lo perdiera devolvería ETag 0
	// contra un documento en la revisión N — el dashboard mandaría ese 0 en
	// `If-Match` y se comería un 409 eterno. Mismo trato que `schema_version`.
	out["rev"] = SerializeValue(m.Rev)
	out["enabled"] = SerializeValue(m.Enabled)
	out["enabled_since"] = nullableDateField(m.EnabledSince)
	out["guild_id"] = SerializeValue(m.GuildID)
	putJSONInline(out, "base_ticket", m.BaseTicket)
	out["log_channel_id"] = nullableStringField(m.LogChannelID)
	out["log_auto_publish"] = SerializeValue(m.LogAutoPublish)
	out["main_guild_id"] = nullableStringField(m.MainGuildID)
	out["special_guild_id"] = nullableStringField(m.SpecialGuildID)
	putJSONInline(out, "colors", m.Colors)
	putJSONInline(out, "message_colors", m.MessageColors)
	putJSONInline(out, "message_images", m.MessageImages)
	putJSONInline(out, "message_footers", m.MessageFooters)
	putJSONInline(out, "message_footer_icons", m.MessageFooterIcons)
	putJSONInline(out, "messages", m.Messages)
	out["command_mode"] = SerializeValue(m.CommandMode)
	putJSONInline(out, "command_triggers", m.CommandTriggers)
	putJSONInline(out, "custom_commands", m.CustomCommands)
	putJSONInline(out, "aliases", m.Aliases)
	putJSONInline(out, "ticket_types", m.TicketTypes)
	putJSONInline(out, "direct_open", m.DirectOpen)
	out["special_types_in_main"] = SerializeValue(m.SpecialTypesInMain)
	out["ticket_type_emojis"] = SerializeValue(m.TicketTypeEmojis)
	// Puntero con backfill en `NormalizeModmail` (nil → true); el guard cubre un
	// subdoc que no haya pasado por ahí para que el marshal nunca haga panic.
	anonIcon := true
	if m.AnonymousIcon != nil {
		anonIcon = *m.AnonymousIcon
	}
	out["anonymous_icon"] = SerializeValue(anonIcon)
	// Gemelo v13 para las respuestas NO anónimas: mismo puntero + backfill.
	identIcon := true
	if m.IdentifiedIcon != nil {
		identIcon = *m.IdentifiedIcon
	}
	out["identified_icon"] = SerializeValue(identIcon)
	putJSONInline(out, "dm_ack_reaction", m.DmAckReaction)
	putJSONInline(out, "staff_message_action_emojis", m.StaffMessageActionEmojis)
	putJSONInline(out, "staff_commands", m.StaffCommands)
	out["contact_category_id"] = nullableStringField(m.ContactCategoryID)
	out["contact_channel_name_template"] = nullableStringField(m.ContactChannelNameTemplate)
	putJSONInline(out, "web_access", m.WebAccess)
	putJSONInline(out, "blacklist", m.Blacklist)
	// nil → "" (DeserializeValue("") = nil → puntero nil al leer), número →
	// SerializeValue: el mismo contrato que los nullables de string del hash.
	out["ticket_cooldown_minutes"] = nullableIntField(m.TicketCooldownMinutes)
	putJSONInline(out, "support_closed", m.SupportClosed)
	putJSONInline(out, "typing_forward", m.TypingForward)
	putJSONInline(out, "support_schedule", m.SupportSchedule)
	return out, nil
}

// MarshalModuleTickets serializes a typed `dbguild.ModuleTickets` subdoc.
// Mirrors the modmail marshaller: scalars (schema_version, enabled,
// ticket_type_emojis) go through SerializeValue; every nested object / array /
// map goes through putJSONInline (JSON); `log_channel_id` uses
// `nullableStringField` so nil → "" (the Node `serializeValue(null) === ""`
