func TestUpdateModuleMusicBodySet_AllFields(t *testing.T) {
	enabled := true
	radioOn := true
	commandsGlobal := dbguild.MusicCommandAccessDefault()
	commands := map[string]dbguild.MusicCommand{
		"play": dbguild.MusicConfigurableCommandDefault(),
	}
	body := UpdateModuleMusicBody{
		SchemaVersion:      intPtr(5),
		Enabled:            &enabled,
		MaxSongDuration:    intPtr(3600),
		Loop:               loopPtr(dbguild.MusicLoopSong),
		Volume:             intPtr(50),
		RadioMode:          &dbguild.RadioMode{Enabled: radioOn, ChannelID: "123"},
		MessageRetention:   boolPtr(true),
		PinnedNowPlaying:   boolPtr(true),
		VoiceStatusEnabled: boolPtr(true),
		EnhancedSearch:     boolPtr(true),
		AudioQuality:       audioQualityPtr(dbguild.MusicAudioQualityHifi),
		CommandsGlobal:     &commandsGlobal,
		Commands:           &commands,
		TextChannels:       &dbguild.ChannelsConfig{Exclude: true, ChannelsID: []string{"1", "2"}},
		VoiceChannels:      &dbguild.ChannelsConfig{Exclude: false, ChannelsID: []string{"3"}},
		DJ: &dbguild.DJ{
			Enabled:     true,
			Roles:       []string{"r1"},
			Commands:    []string{"c1"},
			Vote:        true,
			VoteTimeout: 120,
		},
		RecommendedArtists: &[]string{"Bruno Mars"},
	}

	set := body.Set()
	if len(set) != 17 {
		t.Fatalf("set has %d fields, want 17", len(set))
	}
	if set["schema_version"] != 5 {
		t.Fatalf("schema_version = %v, want 5", set["schema_version"])
	}
	if _, ok := set["commands_global"]; !ok {
		t.Fatalf("commands_global missing from $set")
	}
	if _, ok := set["commands"]; !ok {
		t.Fatalf("commands missing from $set")
	}
	if set["enabled"] != true {
		t.Fatalf("enabled = %v, want true", set["enabled"])
	}
	if set["loop"] != "song" {
		t.Fatalf("loop = %v, want song", set["loop"])
	}
	if set["audio_quality"] != "hifi" {
		t.Fatalf("audio_quality = %v, want hifi", set["audio_quality"])
	}
	if got := set["radio_mode"]; got == nil {
		t.Fatalf("radio_mode not set")
	}
}

func TestUpdateModuleMusicBodySet_Empty(t *testing.T) {
	body := UpdateModuleMusicBody{}
	set := body.Set()
	if set != nil {
		t.Fatalf("empty body should produce nil $set, got %v", set)
	}
}

func TestUpdateModuleMusicBodySet_Partial(t *testing.T) {
	enabled := false
	body := UpdateModuleMusicBody{
		Enabled: &enabled,
		Volume:  intPtr(75),
	}
	set := body.Set()
	if len(set) != 2 {
		t.Fatalf("partial set has %d fields, want 2", len(set))
	}
	if set["enabled"] != false {
		t.Fatalf("enabled = %v, want false", set["enabled"])
	}
	if set["volume"] != 75 {
		t.Fatalf("volume = %v, want 75", set["volume"])
	}
	if _, ok := set["schema_version"]; ok {
		t.Fatalf("schema_version should not be set when nil")
	}
}

func TestUpdateModuleMusicBodyRadioModeEnabled(t *testing.T) {
	// When RadioMode is nil → nil pointer (no change to lavalink).
	body := UpdateModuleMusicBody{}
	if body.RadioModeEnabled() != nil {
		t.Fatalf("RadioModeEnabled should be nil when RadioMode is absent")
	}

	// When RadioMode is present → pointer to its Enabled value.
	off := false
	body = UpdateModuleMusicBody{RadioMode: &dbguild.RadioMode{Enabled: off}}
	got := body.RadioModeEnabled()
	if got == nil || *got != false {
		t.Fatalf("RadioModeEnabled = %v, want pointer to false", got)
	}
}

func TestModuleMusicFieldsMatchDBGuild(t *testing.T) {
	// Compile-time guarantee: every JSON-tagged field of ModuleMusic is
	// present in the musicFieldWhitelist (defined in the handlers
	// package). Drift here means the handler will return 400 for a
	// field that exists in the type — fail loudly here so the test
	// catches it without integration.
	want := map[string]struct{}{}
	t2 := reflect.TypeOf(dbguild.ModuleMusic{})
	for i := range t2.NumField() {
		// El tag puede traer opciones (`enabled_since,omitempty`): la clave es
		// lo anterior a la primera coma, igual que hace el guard de
		// `musicFieldWhitelist` en el handler.
		tag := strings.SplitN(t2.Field(i).Tag.Get("bson"), ",", 2)[0]
		if tag == "" || tag == "-" {
			continue
		}
		want[tag] = struct{}{}
	}
	// Same count for the whitelist via the handlers package's own
	// compile-time assert (cannot import musicFieldWhitelist directly).
	// Smoke-test: every ModuleMusic JSON field is one of the expected
	// 19 keys. Update this list when adding new fields.
	expected := []string{
		"schema_version", "enabled", "enabled_since", "max_song_duration", "loop", "volume",
		"radio_mode", "message_retention", "pinned_now_playing",
		"voice_status_enabled", "enhanced_search", "auto_delete_commands",
		"audio_quality",
		"commands_global", "commands",
		"text_channels", "voice_channels", "dj", "recommended_artists",
	}
	if len(expected) != len(want) {
		t.Fatalf("ModuleMusic has %d bson fields, expected list has %d", len(want), len(expected))
	}
	for _, k := range expected {
		if _, ok := want[k]; !ok {
			t.Fatalf("expected field %q missing from ModuleMusic", k)
		}
	}
}

