func intPtr(v int) *int    { return &v }
func boolPtr(v bool) *bool { return &v }
func loopPtr(v dbguild.MusicLoop) *dbguild.MusicLoop {
	return &v
}
func audioQualityPtr(v dbguild.MusicAudioQuality) *dbguild.MusicAudioQuality {
	return &v
}

