func TestModuleEnabledQuery_OneofViolation(t *testing.T) {
	v := NewValidator()
	q := ModuleEnabledQuery{Module: "bogus"}
	if err := v.Struct(q); err == nil {
		t.Fatalf("expected validation error for invalid module key, got nil")
	}
}

// TestModuleEnabledQuery_EmptyValid — sin query, válido.
func TestModuleEnabledQuery_EmptyValid(t *testing.T) {
	v := NewValidator()
	if err := v.Struct(ModuleEnabledQuery{}); err != nil {
		t.Fatalf("empty query should validate: %v", err)
	}
}

// TestModuleEnabledQuery_AllValidValues — los 3 valores canónicos validan.
func TestModuleEnabledQuery_AllValidValues(t *testing.T) {
	v := NewValidator()
	for _, m := range []string{"music", "greeter", "logs"} {
