package validations

import (
	"regexp"

	"kena.bot/api-db-go/internal/domain/dbbot"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// Request DTOs + parsers for the `/bots` router. Field shapes mirror the Zod
// schemas in `services/api-db/src/domain/zod-schemas/validations/bot-validations.ts`
// and `.../mongo/bot-schema.ts`.
//
// Unlike the `/commands` bodies (which have no top-level defaults and lean on
// struct-tag validation), every bot field carries a zod/mongoose write-time
// default, so the bodies are parsed MANUALLY with pointer fields: a nil pointer
// means "absent" (take the default / skip the `$set`), a non-nil pointer means
// "the client sent this" (validate the enum, force it into the `$set`). This
// reproduces zod's "present-but-invalid → throw, absent → default" semantics
// exactly, which struct tags can't express for optional-with-default fields.

// zodItemError builds the CustomError shape `zodErrorToResultData` produces on
// the Node side: one `ZodItemError` per issue — `context:"ZOD"`, `type:"VALIDATION"`,
// `statusCode:400`, empty `code`, and `metadata.property = issue.path.join(".")`.
// The refine (owner_id-if-custom) has an empty path, so `property` is "".
func zodItemError(message, property string) *apierrors.CustomError {
	return apierrors.New(apierrors.Props{
		Message:    message,
		Context:    apierrors.ContextZod,
		Type:       apierrors.TypeValidation,
		Metadata:   map[string]any{"property": property},
		StatusCode: apierrors.StatusBadRequest,
	})
}

