		t.Fatalf("nil body should validate, got %v", err)
	}
}

func TestValidateUpdateModuleLeveling_UntouchedBlocksSkip(t *testing.T) {
	// Text/Voice ausentes del PATCH -> nil, nunca se valida su bloque de
	// requisitos.
	body := UpdateModuleLevelingBody{}
	if err := ValidateUpdateModuleLeveling(&body); err != nil {
		t.Fatalf("body with no text/voice should validate, got %v", err)
	}
}

func TestValidateUpdateModuleLeveling_ZeroRequirementsValid(t *testing.T) {
	// Todo el bloque a 0/false/vacío (el default de fábrica) debe validar:
	// es la representación de "sin requisito".
	body := UpdateModuleLevelingBody{
		Text: &dbguild.LevelingXpSource{Requirements: dbguild.LevelingRequirements{}},
	}
	if err := ValidateUpdateModuleLeveling(&body); err != nil {
		t.Fatalf("zero-value requirements should validate, got %v", err)
	}
}

func TestValidateUpdateModuleLeveling_MinMembershipSecondsTooBig(t *testing.T) {
	body := UpdateModuleLevelingBody{
		Text: &dbguild.LevelingXpSource{
			Requirements: dbguild.LevelingRequirements{MinMembershipSeconds: maxLevelingRequirementAgeSeconds + 1},
		},
	}
	err := ValidateUpdateModuleLeveling(&body)
	if err == nil {
		t.Fatal("expected error for min_membership_seconds over the cap")
	}
	if err.Metadata["property"] != "text.requirements.min_membership_seconds" {
		t.Fatalf("property = %v, want text.requirements.min_membership_seconds", err.Metadata["property"])
	}
}

