	body := UpdateModuleLevelingBody{
		Voice: &dbguild.LevelingXpSource{
			Requirements: dbguild.LevelingRequirements{MinAccountAgeSeconds: -1},
		},
	}
	err := ValidateUpdateModuleLeveling(&body)
	if err == nil {
		t.Fatal("expected error for negative min_account_age_seconds")
	}
	if err.Metadata["property"] != "voice.requirements.min_account_age_seconds" {
		t.Fatalf("property = %v, want voice.requirements.min_account_age_seconds", err.Metadata["property"])
	}
}

