	body := UpdateModuleLevelingBody{
		Text: &dbguild.LevelingXpSource{
			Requirements: dbguild.LevelingRequirements{MinMessageLength: maxLevelingRequirementMessageLength + 1},
		},
	}
	err := ValidateUpdateModuleLeveling(&body)
	if err == nil {
		t.Fatal("expected error for min_message_length over the Discord message cap")
	}
	if err.Metadata["property"] != "text.requirements.min_message_length" {
		t.Fatalf("property = %v, want text.requirements.min_message_length", err.Metadata["property"])
	}
}

