	body := UpdateModuleLevelingBody{
		Text: &dbguild.LevelingXpSource{
			Requirements: dbguild.LevelingRequirements{BypassRoleIDs: []string{"not-a-snowflake"}},
		},
	}
	err := ValidateUpdateModuleLeveling(&body)
	if err == nil {
		t.Fatal("expected error for a non-snowflake bypass_role_ids entry")
	}
	if err.Metadata["property"] != "text.requirements.bypass_role_ids" {
		t.Fatalf("property = %v, want text.requirements.bypass_role_ids", err.Metadata["property"])
	}
}

func TestValidateUpdateModuleLeveling_BypassRoleIDsValidSnowflake(t *testing.T) {
	body := UpdateModuleLevelingBody{
		Voice: &dbguild.LevelingXpSource{
			Requirements: dbguild.LevelingRequirements{BypassRoleIDs: []string{"123456789012345678"}},
		},
	}
	if err := ValidateUpdateModuleLeveling(&body); err != nil {
		t.Fatalf("valid snowflake should validate, got %v", err)
	}
}

